import os
import re
import subprocess
import json
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/monitor/commands', methods=['POST'])
def monitor_commands():
    data = request.get_json(silent=True)
    if not data or 'command_regex' not in data:
        return jsonify({"error": "Missing command_regex"}), 400

    command_regex = data.get('command_regex')
    filter_flags = data.get('filter_flags', 'aux')

    try:
        regex_pattern = re.compile(command_regex)
    except re.error:
        return jsonify({"error": "Invalid regular expression"}), 400

    try:
        ps_command = ['ps', filter_flags]
        result = subprocess.run(ps_command, capture_output=True, text=True, timeout=10)
        if result.returncode != 0:
            return jsonify({"error": "Failed to run ps command"}), 500

        process_lines = result.stdout.splitlines()
        header = process_lines[0] if process_lines else ""
        processes = []

        for line in process_lines[1:]:
            if not line.strip():
                continue
            parts = line.split()
            if not parts:
                continue
            pid_str = parts[0]
            try:
                pid = int(pid_str)
            except ValueError:
                continue

            # Reconstruct the command string from the remaining parts
            # On Linux ps aux output, the command is usually the last field or can contain spaces
            cmd_string = ' '.join(parts[1:]) if len(parts) > 1 else ""

            if regex_pattern.search(cmd_string):
                processes.append({
                    "processId": pid,
                    "processString": cmd_string
                })

        return jsonify(processes), 200

    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
